<script setup>
import { computed, onMounted, ref } from 'vue';
import { Award, Trophy, Medal, Star, Lock, CircleCheck, BookOpen, Brain, Flame, Target, CalendarCheck2, TrendingUp, GraduationCap, Sparkles, Crown, RefreshCw, Search } from 'lucide-vue-next';
import { useAuthStore } from '~/stores/api/auth';
import { useUserAchievementsStore } from '~/stores/api/userAchievements';
import { canAccessPage } from '~/utils/roles';
definePageMeta({ layout: 'default' });
const auth = useAuthStore(), store = useUserAchievementsStore(), ready = ref(false), search = ref('');
const icons = { Award, Trophy, Medal, Star, BookOpen, Brain, Flame, Target, CalendarCheck2, TrendingUp, GraduationCap, Sparkles, Crown, CircleCheck };
const categories = { learning: 'Belajar', practice: 'Practice', consistency: 'Konsistensi', tryout: 'Tryout', roadmap: 'Roadmap', mastery: 'Mastery', special: 'Spesial' };
const rarityLabels = { common: 'Common', rare: 'Rare', epic: 'Epic', legendary: 'Legendary' };
const rarityTone = { common: 'bg-pale-blue text-primary-container', rare: 'bg-emerald-50 text-emerald-700', epic: 'bg-purple-50 text-purple-700', legendary: 'bg-amber-50 text-amber-700' };
const card = 'min-w-0 rounded-3xl border border-soft-blue bg-surface-white p-4 shadow-sm sm:p-6';
const number = value => Number(value || 0).toLocaleString('id-ID', { maximumFractionDigits: 1 });
const date = value => value ? new Date(value).toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' }) : '—';
const visible = computed(() => store.achievements.filter(item => !search.value.trim() || `${item.name} ${item.description}`.toLowerCase().includes(search.value.trim().toLowerCase())));
const cards = computed(() => [
  { label: 'Achievement Terbuka', value: number(store.summary?.unlocked), icon: Award },
  { label: 'Badge Langka', value: number(store.summary?.rare_badges), icon: Medal },
  { label: 'Current Streak', value: `${number(store.summary?.current_streak)} hari`, icon: Flame },
  { label: 'Total XP', value: `${number(store.summary?.total_xp)} XP`, icon: Star },
]);
onMounted(async () => { auth.initializeAuth(); if (!auth.token) return navigateTo('/login'); const user = await auth.fetchCurrentUser(); if (Number(user?.role) !== 2 || !canAccessPage(user?.role, 'achievements.self')) return navigateTo('/dashboard'); ready.value = true; await store.fetchAchievements(); });
</script>
<template>
  <div class="mx-auto w-full max-w-[1600px] min-w-0 px-4 py-5 text-on-surface sm:px-6 sm:py-7 lg:px-8"><header class="mb-5"><div class="inline-flex items-center gap-2 rounded-full bg-pale-blue px-3 py-1 text-xs font-semibold text-primary-container"><Award class="h-4 w-4" /> Perjalanan Belajar</div><h1 class="mt-3 text-2xl font-bold sm:text-3xl">Achievements</h1><p class="mt-1 text-sm text-on-surface-variant">Lihat pencapaian, milestone, dan perjalanan belajarmu di MatrIQ.</p><p v-if="store.summary" class="mt-2 text-xs text-outline">{{ store.summary.total }} achievement · {{ store.summary.unlocked }} terbuka · {{ store.summary.locked }} terkunci</p></header>
    <div v-if="store.error" role="alert" class="mb-5 flex items-center justify-between gap-3 rounded-2xl border border-rose-200 bg-white p-4 text-sm text-rose-700"><span>{{ store.error }}</span><button class="inline-flex items-center gap-2 font-semibold" @click="store.refreshAchievements()"><RefreshCw class="h-4 w-4" /> Coba Lagi</button></div>
    <div v-if="!ready || (store.isLoading && !store.summary)" class="space-y-4" aria-label="Memuat achievement"><div class="grid grid-cols-2 gap-3 lg:grid-cols-4"><div v-for="i in 4" :key="i" class="h-28 animate-pulse rounded-3xl bg-slate-200" /></div><div class="h-40 animate-pulse rounded-3xl bg-slate-200" /><div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-3"><div v-for="i in 3" :key="i" class="h-48 animate-pulse rounded-3xl bg-slate-200" /></div></div>
    <template v-else><section class="mb-5 grid grid-cols-2 gap-3 lg:grid-cols-4"><article v-for="item in cards" :key="item.label" :class="card"><component :is="item.icon" class="mb-3 h-5 w-5 text-primary-container" /><p class="text-xs text-outline">{{ item.label }}</p><strong class="mt-1 block text-xl">{{ item.value }}</strong></article></section>
      <div v-if="store.summary?.total" class="mb-5 grid gap-4 lg:grid-cols-2"><section :class="card"><h2 class="mb-3 font-bold">Pencapaian Terbaru</h2><div v-if="store.latestAchievements.length" class="space-y-2"><article v-for="item in store.latestAchievements" :key="item.code" class="flex items-center gap-3 rounded-xl bg-surface-container-low p-3"><component :is="icons[item.icon] || Award" class="h-5 w-5 shrink-0 text-primary-container" /><span class="min-w-0 flex-1"><strong class="block truncate text-sm">{{ item.name }}</strong><small class="text-outline">Diperoleh {{ date(item.unlocked_at) }}</small></span><span class="text-xs font-semibold text-primary-container">+{{ item.xp_reward }} XP</span></article></div><div v-else class="py-5 text-center"><p class="font-semibold">Perjalananmu baru dimulai 🚀</p><p class="mt-1 text-sm text-outline">Selesaikan materi, Practice, dan Study Plan untuk membuka achievement pertamamu.</p><NuxtLink to="/practice" class="mt-3 inline-block text-sm font-semibold text-primary-container">Mulai Practice</NuxtLink></div></section><section :class="card"><h2 class="mb-3 font-bold">Hampir Tercapai</h2><div v-if="store.almostUnlocked.length" class="space-y-3"><article v-for="item in store.almostUnlocked" :key="item.code"><div class="flex justify-between gap-2 text-sm"><strong>{{ item.name }}</strong><span>{{ number(item.progress_value) }} / {{ number(item.target_value) }}</span></div><div class="mt-2 h-2 rounded-full bg-surface-container"><div class="h-full rounded-full bg-primary-container" :style="{ width: `${item.progress_percent}%` }" /></div><p class="mt-1 text-xs text-outline">{{ item.description }}</p></article></div><p v-else class="py-5 text-sm text-outline">Belum ada badge yang hampir tercapai. Mulai aktivitas belajar untuk mengisi progres.</p></section></div>
      <section :class="card"><div class="mb-4 flex flex-wrap items-center justify-between gap-3"><h2 class="font-bold">Semua Achievement</h2><div class="flex flex-wrap gap-2"><label class="relative"><Search class="absolute left-3 top-2.5 h-4 w-4 text-outline" /><input v-model="search" type="search" placeholder="Cari achievement..." class="w-44 rounded-xl border border-soft-blue bg-surface-container-low py-2 pl-9 pr-3 text-sm outline-none focus:border-primary-container sm:w-52" /></label><select :value="store.filters.status" class="rounded-xl border border-soft-blue bg-surface-container-low px-3 py-2 text-sm" aria-label="Filter status" @change="store.setStatus($event.target.value)"><option value="all">Semua</option><option value="unlocked">Terbuka</option><option value="locked">Terkunci</option></select><select :value="store.filters.category" class="rounded-xl border border-soft-blue bg-surface-container-low px-3 py-2 text-sm" aria-label="Filter kategori" @change="store.setCategory($event.target.value)"><option value="">Semua Kategori</option><option v-for="(label,key) in categories" :key="key" :value="key">{{ label }}</option></select><select :value="store.filters.rarity" class="rounded-xl border border-soft-blue bg-surface-container-low px-3 py-2 text-sm" aria-label="Filter rarity" @change="store.setRarity($event.target.value)"><option value="">Semua Rarity</option><option v-for="(label,key) in rarityLabels" :key="key" :value="key">{{ label }}</option></select></div></div><div v-if="store.isLoading" class="grid gap-3 sm:grid-cols-2 xl:grid-cols-3"><div v-for="i in 3" :key="i" class="h-44 animate-pulse rounded-2xl bg-slate-200" /></div><div v-else-if="visible.length" class="grid gap-3 sm:grid-cols-2 xl:grid-cols-3"><article v-for="item in visible" :key="item.code" class="min-w-0 rounded-2xl border border-soft-blue p-4" :class="item.status === 'locked' ? 'opacity-75' : ''"><div class="flex items-start justify-between gap-2"><div class="flex h-10 w-10 items-center justify-center rounded-xl" :class="rarityTone[item.rarity]"><component :is="item.status === 'locked' ? Lock : icons[item.icon] || Award" class="h-5 w-5" /></div><span class="rounded-full px-2 py-1 text-[11px] font-semibold" :class="rarityTone[item.rarity]">{{ rarityLabels[item.rarity] }}</span></div><h3 class="mt-3 font-semibold">{{ item.name }}</h3><p class="mt-1 min-h-10 text-xs text-on-surface-variant">{{ item.description }}</p><p class="mt-1 text-xs text-outline">{{ categories[item.category] }} · +{{ item.xp_reward }} XP</p><div class="mt-4 flex items-center justify-between text-xs"><span>{{ item.status === 'unlocked' ? `Diperoleh ${date(item.unlocked_at)}` : 'Terkunci' }}</span><strong>{{ number(item.progress_value) }} / {{ number(item.target_value) }}</strong></div><div class="mt-2 h-2 rounded-full bg-surface-container"><div class="h-full rounded-full bg-primary-container" :style="{ width: `${item.progress_percent}%` }" /></div></article></div><p v-else class="py-10 text-center text-sm text-outline">{{ store.summary?.total ? 'Achievement tidak ditemukan untuk filter ini.' : 'Belum ada achievement tersedia.' }}</p></section>
    </template>
  </div>
</template>
